AAErisaidActor::AAErisaidActor()
{
	PrimaryActorTick.bCanEverTick = true;

	// Create shell root component
	ShellRoot = CreateDefaultSubobject<USceneComponent>(TEXT("ShellRoot"));
	RootComponent = ShellRoot;

	// Create interaction sphere (larger than visual shell for detection)
	InteractionSphere = CreateDefaultSubobject<USphereComponent>(TEXT("InteractionSphere"));
	InteractionSphere->SetupAttachment(ShellRoot);
	InteractionSphere->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
	InteractionSphere->SetCollisionProfileName("Trigger");
	InteractionSphere->SetSphereRadius(1500.0f);  // ~15m detection radius

	// Create spore cloud particle system (hidden until Captive Burst)
	SporeCloud = CreateDefaultSubobject<UParticleSystemComponent>(TEXT("SporeCloud"));
	SporeCloud->SetupAttachment(ShellRoot);
	SporeCloud->bAutoActivate = false;  // Activated on Captive Burst

	// Create interior volume for contraction detection
	InteriorVolume = CreateDefaultSubobject<UBoxComponent>(TEXT("InteriorVolume"));
	InteriorVolume->SetupAttachment(ShellRoot);
	InteriorVolume->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
	InteriorVolume->SetBoxExtent(FVector(500.0f, 500.0f, 300.0f));  // ~5m radius

	// Initialize default state
	CurrentState = EShellState::Inert_Buried;
	RespirationPhase = ERespirationPhase::Expansion;
	bBeaconInserted = false;
}

void AAErisaidActor::BeginPlay()
{
	Super::BeginPlay();

	// Register overlap events on interaction sphere
	if (InteractionSphere)
	{
		InteractionSphere->OnComponentBeginOverlap.AddDynamic(this, &AAErisaidActor::OnInteractionSphereOverlap);
		InteractionSphere->OnComponentEndOverlap.AddDynamic(this, &AAErisaidActor::OnInteractionSphereUnoverlap);
	}

	// Log shell activation
	UE_LOG(LogTemp, Log, TEXT("AErisaidActor activated at %s"), *GetActorLocation().ToString());
}

void AAErisaidActor::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);

	// Update respiration cycle timer
	RespirationTimer += DeltaSeconds;

	if (RespirationPhase == ERespirationPhase::Contraction)
	{
		// Contraction is active - periodically spawn shell mites
		// and collapse interior volume
	}
	else if (RespirationPhase == ERespirationPhase::Expansion)
	{
		// Expansion phase - interior is stable
	}
}

